{
  "settings": [
    {
      "name": "secret_directory",
      "input_type": "VARCHAR",
      "scope": "LOCAL",
      "evidence": "To change the secrets directory, issue:\n\n```sql\nSET secret_directory = 'path/to/my_secrets_dir';\n```\n\nThe `secret_directory` setting applies to the current DuckDB instance and is not persisted across DuckDB instances.",
      "default_kind": "literal",
      "default_value": "~/.duckdb/stored_secrets",
      "default_evidence": "By default, this will write the secret (unencrypted) to the `~/.duckdb/stored_secrets` directory."
    }
  ]
}
